# Windows kurulum katmanındaki ilk oturum hazırlığı için; disk biçimlendirmez.
# İlk oturum ve rapor kopyası ayrı Windows laboratuvarında doğrulanmıştır.
[CmdletBinding()]
param([string]$ReportSource, [string]$ExpectedManifestHash, [string]$PreviewPath)
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Drawing

function New-TestWallpaper([string]$Destination) {
    $bitmap = [Drawing.Bitmap]::new(1920, 1080)
    $graphics = [Drawing.Graphics]::FromImage($bitmap)
    $graphics.SmoothingMode = [Drawing.Drawing2D.SmoothingMode]::AntiAlias
    $graphics.TextRenderingHint = [Drawing.Text.TextRenderingHint]::AntiAliasGridFit
    $background = [Drawing.Drawing2D.LinearGradientBrush]::new(
        [Drawing.Point]::new(0,0), [Drawing.Point]::new(1920,1080),
        [Drawing.Color]::FromArgb(5,30,70), [Drawing.Color]::FromArgb(12,91,182))
    $graphics.FillRectangle($background, 0, 0, 1920, 1080)
    $cyan = [Drawing.SolidBrush]::new([Drawing.Color]::FromArgb(65,211,239))
    $white = [Drawing.SolidBrush]::new([Drawing.Color]::FromArgb(234,244,250))
    $green = [Drawing.SolidBrush]::new([Drawing.Color]::FromArgb(95,227,161))
    $amber = [Drawing.SolidBrush]::new([Drawing.Color]::FromArgb(255,203,108))
    $panel = [Drawing.SolidBrush]::new([Drawing.Color]::FromArgb(26,43,62))
    $title = [Drawing.Font]::new('Segoe UI', 88, [Drawing.FontStyle]::Bold)
    $subtitle = [Drawing.Font]::new('Segoe UI', 25)
    $notice = [Drawing.Font]::new('Segoe UI', 25, [Drawing.FontStyle]::Bold)
    $linkFont = [Drawing.Font]::new('Segoe UI', 20)
    $logoStream = [IO.MemoryStream]::new([Convert]::FromBase64String(''))
    $logo = [Drawing.Image]::FromStream($logoStream)
    try {
        $graphics.DrawImage($logo, 1400, 190, 290, 257)
        $graphics.FillRectangle($cyan, 140, 210, 10, 230)
        $graphics.DrawString('VEDT', $title, $white, 185, 200)
        $graphics.DrawString('Vektron Elektronik Disk Test', $subtitle, $white, 195, 340)
        $graphics.DrawString('DİSK TESTİ İÇİN HAZIRLANMIŞ GEÇİCİ SİSTEM', $subtitle, $cyan, 195, 400)
        $graphics.DrawString('Raporlar masaüstündeki VEDT-Rapor klasöründedir.', $subtitle, $green, 195, 460)
        $graphics.DrawString('github.com/nusretcankarakus/VEDT', $linkFont, $cyan, 195, 520)
        $graphics.DrawString('Türkçe rapor okuma kılavuzu ve açık kaynak kodu GitHub üzerinde.', $linkFont, $white, 195, 565)
        $graphics.FillRectangle($panel, 140, 660, 1640, 220)
        $graphics.FillRectangle($amber, 140, 660, 8, 220)
        $graphics.DrawString('KİŞİSEL KULLANIMDAN ÖNCE', $notice, $amber, 185, 695)
        $graphics.DrawString('Güvenliğiniz için diski silerek temiz Windows kurulumu yapın.', $subtitle, $white, 185, 755)
        $parent = Split-Path -Parent $Destination
        if (-not (Test-Path -LiteralPath $parent)) { New-Item -ItemType Directory -Path $parent | Out-Null }
        $bitmap.Save($Destination, [Drawing.Imaging.ImageFormat]::Png)
    } finally {
        foreach ($object in @($logo,$logoStream,$title,$subtitle,$notice,$linkFont,$background,$cyan,$white,$green,$amber,$panel,$graphics,$bitmap)) {
            $object.Dispose()
        }
    }
}

if ($PreviewPath) {
    New-TestWallpaper ([IO.Path]::GetFullPath($PreviewPath))
    return  # Önizleme kayıt defterine veya masaüstüne dokunmaz.
}
if (-not $ReportSource) { throw 'Doğrulanmış rapor klasörü gerekli.' }
if ($env:USERNAME -notmatch '^VEDT[1-9][0-9]{0,14}$') { throw 'Bu hazırlık VEDT kullanıcısının ilk oturumunda çalışmalıdır.' }
$sourceRoot = (Resolve-Path -LiteralPath $ReportSource).Path
if ($ExpectedManifestHash -notmatch '^[a-fA-F0-9]{64}$') { throw 'Test aşamasının kaydettiği güvenilir rapor özeti gerekli.' }
if ((Get-FileHash -LiteralPath (Join-Path $sourceRoot 'manifest.json') -Algorithm SHA256).Hash -ne $ExpectedManifestHash) {
    throw 'Rapor özeti test aşamasındaki kayıtla eşleşmiyor.'
}
$manifest = Get-Content -LiteralPath (Join-Path $sourceRoot 'manifest.json') -Raw -Encoding UTF8 | ConvertFrom-Json
if ($manifest.algorithm -ne 'SHA-256') { throw 'Desteklenmeyen dosya özeti yöntemi.' }
foreach ($required in @('report.pdf','report.html','session.json')) {
    if ($required -notin @($manifest.files.PSObject.Properties.Name)) { throw 'Zorunlu rapor dosyası eksik.' }
}
foreach ($entry in $manifest.files.PSObject.Properties) {
    if ([IO.Path]::GetFileName($entry.Name) -ne $entry.Name -or $entry.Name -match '[\\/]' -or $entry.Name -eq 'manifest.json') { throw 'Geçersiz rapor yolu.' }
    $sourceFile = Join-Path $sourceRoot $entry.Name
    if ((Get-FileHash -LiteralPath $sourceFile -Algorithm SHA256).Hash.ToLower() -ne $entry.Value) { throw 'Rapor özeti uyuşmuyor.' }
}
$desktop = [Environment]::GetFolderPath('DesktopDirectory')
$destination = Join-Path $desktop 'VEDT-Rapor'
if (-not (Test-Path -LiteralPath $destination)) {
    New-Item -ItemType Directory -Path $destination -ErrorAction Stop | Out-Null
} elseif ((Get-Item -LiteralPath $destination).Attributes -band [IO.FileAttributes]::ReparsePoint) {
    throw 'Rapor klasörü bir bağlantı olamaz.'
}
foreach ($name in @($manifest.files.PSObject.Properties.Name) + @('manifest.json')) {
    $targetFile = Join-Path $destination $name
    if (Test-Path -LiteralPath $targetFile) {
        if ((Get-FileHash -LiteralPath $targetFile -Algorithm SHA256).Hash -ne (Get-FileHash -LiteralPath (Join-Path $sourceRoot $name) -Algorithm SHA256).Hash) { throw 'Var olan rapor farklı; üzerine yazılmadı.' }
    } else {
        Copy-Item -LiteralPath (Join-Path $sourceRoot $name) -Destination $targetFile
    }
}
foreach ($entry in $manifest.files.PSObject.Properties) {
    if ((Get-FileHash -LiteralPath (Join-Path $destination $entry.Name) -Algorithm SHA256).Hash.ToLower() -ne $entry.Value) {
        throw 'Masaüstü nüshası doğrulanamadı.'
    }
}
$wallpaper = Join-Path $env:LOCALAPPDATA 'DiskTest86\wallpaper.png'
New-TestWallpaper $wallpaper
Set-ItemProperty -LiteralPath 'HKCU:\Control Panel\Desktop' -Name Wallpaper -Value $wallpaper
Set-ItemProperty -LiteralPath 'HKCU:\Control Panel\Desktop' -Name WallpaperStyle -Value '10'
Set-ItemProperty -LiteralPath 'HKCU:\Control Panel\Desktop' -Name TileWallpaper -Value '0'
Add-Type 'using System.Runtime.InteropServices; public class DiskTestWallpaper { [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern bool SystemParametersInfo(int a, int b, string c, int d); }'
if (-not [DiskTestWallpaper]::SystemParametersInfo(20,0,$wallpaper,3)) { throw 'Duvar kâğıdı uygulanamadı.' }

$shortcut = Join-Path $desktop 'VEDT-GitHub.url'
if (-not (Test-Path -LiteralPath $shortcut)) {
    '[InternetShortcut]','URL=https://github.com/nusretcankarakus/VEDT' | Set-Content -LiteralPath $shortcut -Encoding ASCII
}
